INSERT INTO tasks VALUES('t-arch','p-gtte',NULL,0,'Write docs/02-architecture.md','Write the L0-L4 architecture doc with YAML frontmatter (agent-first format). Include: mermaid diagram of layers, per-layer intent table, ownership table (vendored vs built), data flow diagram. Reference diagrams/layers.mmd and diagrams/kernel-services.mmd. Cross-link to chief-kernel, security-model, base-and-hardware. Keep dense — tables, lists, mermaid over prose. Status: draft.','done','code',10,'default','2026-04-21 20:01:32','2026-04-21 20:01:32','2026-04-21 20:02:18','{"diagrams_embedded":2,"file":"docs/02-architecture.md","sections":["tldr","layer-map","intent","ownership","channel-parity","action-lifecycle","process-model","boot-sequence","agent-pov","acceptance","open-questions"]}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-21 20:01:32',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-21 19:59:04','2026-04-21 20:02:18');
INSERT INTO tasks VALUES('t-kernel','p-gtte',NULL,0,'Write docs/03-chief-kernel.md','L2 kernel services deep-dive. 6 services: Agent Runtime, Capability Broker, Memory Graph, Provenance Log, Trust Ledger, Region Router, Event Bus. Each service: responsibilities, API contract, storage, dependencies, acceptance. Include mermaid service diagram. CRITICAL: document the agent-harness abstraction point (opencode v0, swappable). Dense tables.','done','code',9,'default','2026-04-21 20:02:18','2026-04-21 20:02:18','2026-04-21 20:03:17','{"file":"docs/03-chief-kernel.md","harness_swap_point_defined":true,"services_documented":7}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-21 20:02:18',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-21 19:59:19','2026-04-21 20:03:17');
INSERT INTO tasks VALUES('t-modules','p-gtte',NULL,0,'Write docs/04-module-system.md','Capability Packs as Nix flakes. Pack schema (agents, tools, ingesters, panes, rituals, policies, grants). Registry design (official/community/private tiers). Stacks (forkable bundles). Governance UI. Include example pack flake + pack-lifecycle mermaid. Tie to Chief-of-Staff Stack as flagship.','done','code',8,'default','2026-04-21 20:04:18','2026-04-21 20:04:18','2026-04-21 20:05:15','{"file":"docs/04-module-system.md","pack_schema":"defined","stacks_as_viral_unit":true}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-21 20:04:18',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-21 19:59:19','2026-04-21 20:05:15');
INSERT INTO tasks VALUES('t-surfaces','p-gtte',NULL,0,'Write docs/05-surfaces.md','L4 surfaces: Morning Brief, Live Agent View, Provenance Explorer, Ceremony UI, Chat, Trust Ledger viewer, Quarterly Review. Each: purpose, inputs (reads from L2), interactions, friction tier mapping. Apple-design principles applied. Mermaid for Morning Brief render flow.','done','code',8,'default','2026-04-21 20:05:15','2026-04-21 20:05:15','2026-04-21 20:08:45','{"file":"docs/05-surfaces.md","flagship":"Morning Brief","surfaces_documented":7}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-21 20:05:15',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-21 19:59:19','2026-04-21 20:08:45');
INSERT INTO tasks VALUES('t-sec-model','p-gtte',NULL,0,'Write docs/06-security-model.md','Capability-based security from hardware up. Trust chain: TPM/Secure Enclave -> user key -> principal -> capability set -> call-site check -> sandbox -> provenance. Threat model: malicious packs, compromised cloud twin, stolen device, supply chain. Approval ceremony cryptography. Include approval-flow mermaid.','done','code',9,'default','2026-04-21 20:03:17','2026-04-21 20:03:17','2026-04-21 20:04:18','{"ceremony_flow_defined":true,"file":"docs/06-security-model.md","threat_actors_modeled":8}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-21 20:03:17',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-21 19:59:58','2026-04-21 20:04:18');
INSERT INTO tasks VALUES('t-base-hw','p-gtte',NULL,0,'Write docs/07-base-and-hardware.md','NixOS choice justified (scoring table vs Fuchsia, seL4, FreeBSD+Capsicum, illumos, custom). Deploy targets (bare-metal ISO, macOS-host VM image, bootable USB — all from one Nix flake). Hardware requirements (TPM/Secure Enclave mandatory, YubiKey optional). Wayland reasoning. microVM reasoning. Boot time target (<10s). Link adr-0001.','done','code',7,'default','2026-04-21 20:09:44','2026-04-21 20:09:44','2026-04-21 20:10:44','{"base":"NixOS/Linux","deploy_targets":["iso","vm","usb"],"file":"docs/07-base-and-hardware.md"}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-21 20:09:44',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-21 20:00:02','2026-04-21 20:10:44');
INSERT INTO tasks VALUES('t-mem-sub','p-gtte',NULL,0,'Write docs/08-memory-substrate.md','Memory graph as kernel service (not a lib). Schema: nodes (email, file, person, event, decision, artifact, thought, finding), edges (derived-from, replied-to, depends-on, refers-to). URI scheme mem://<type>/<hash>. Horizon tags (short/medium/long/open). Retrieval strategies per surface. Embeddings policy. Backup/encryption. Mermaid schema diagram.','done','code',8,'default','2026-04-21 20:08:45','2026-04-21 20:08:45','2026-04-21 20:09:44','{"file":"docs/08-memory-substrate.md","schema_typed":true,"uri_scheme":"mem://<type>/<hash>"}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-21 20:08:45',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-21 20:00:04','2026-04-21 20:09:44');
INSERT INTO tasks VALUES('t-runtime','p-gtte',NULL,0,'Write docs/09-local-vs-cloud.md','Hybrid runtime split. Three classes: hot-path reasoning (cloud), sensitive reasoning (local), always-on state (local with cloud encrypted replica). Routing rules. Local model spec (Qwen/Llama quantized, 13-32B). Cloud twin spec (stateless, agent-ephemeral). Network-cable-yank demo guarantees.','done','code',7,'default','2026-04-21 20:13:29','2026-04-21 20:13:29','2026-04-21 20:14:17','{"classes":3,"cloud_twin_stateless":true,"file":"docs/09-local-vs-cloud.md"}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-21 20:13:29',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-21 20:00:06','2026-04-21 20:14:17');
INSERT INTO tasks VALUES('t-viral','p-gtte',NULL,0,'Write docs/10-viral-loop.md','The Morning Reveal hero video (90s storyboard, beat-by-beat). ''Try your own Morning Brief'' web preview funnel (OAuth -> cloud-rendered preview -> shareable signed artifact). Forkable Stacks as second viral loop. Public Stack registry. Social mechanics. Reference diagrams/night-morning-loop.mmd.','done','code',7,'default','2026-04-21 20:14:17','2026-04-21 20:14:17','2026-04-21 20:15:21','{"file":"docs/10-viral-loop.md","hero_video_beats":9,"viral_loops":4}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-21 20:14:17',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-21 20:00:13','2026-04-21 20:15:21');
INSERT INTO tasks VALUES('t-oss-biz','p-gtte',NULL,0,'Write docs/11-open-source-business.md','Licensing tiers: AGPL-3.0 kernel+surfaces; Apache-2.0 first-party packs; author-choice community packs. Monetization: hosted cloud twin, managed pack registry, support contracts. Revenue model: 9/mo entry, 49/mo pro. COGS modeling. Enterprise path (v3+) via managed offering. Not selling the software.','done','code',6,'default','2026-04-21 20:20:01','2026-04-21 20:20:01','2026-04-21 20:21:38','{"file":"docs/11-open-source-business.md","license":"AGPL kernel / Apache packs","margin":"~50-63%","tiers":4}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-21 20:20:01',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-21 20:00:16','2026-04-21 20:21:38');
INSERT INTO tasks VALUES('t-apple-des','p-gtte',NULL,0,'Write docs/12-apple-design-principles.md','10 Apple-inspired product principles applied to Chief OS: one way to do each thing, hide complexity reveal power, defaults beautiful, rituals not workflows, typography as substance, sound as chrome, continuity, physics over animation, demo as gate, privacy as UX. Each with a Chief-OS-specific guardrail.','done','code',6,'default','2026-04-21 20:22:50','2026-04-21 20:22:50','2026-04-21 20:23:38','{"anti_patterns_listed":7,"file":"docs/12-apple-design-principles.md","principles":10}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-21 20:22:50',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-21 20:00:20','2026-04-21 20:23:38');
INSERT INTO tasks VALUES('t-reg','p-gtte',NULL,0,'Write docs/15-regulatory-posture.md','''Machine as fax'' legal posture for v0-v1. Every external action requires signed approval token; human is legal actor. E-signature legality (ESIGN/UETA in US, eIDAS in EU). Money rails for v1+ (via licensed partners: Stripe Issuing, Plaid, Modern Treasury). KYC on human, not agent. Glide path to v2 money/legal ceremony. Jurisdictions of concern.','done','code',6,'default','2026-04-21 20:23:38','2026-04-21 20:23:38','2026-04-21 20:26:07','{"file":"docs/15-regulatory-posture.md","frameworks_covered":["ESIGN","UETA","eIDAS","GDPR","EU-AI-Act","HIPAA"],"posture":"machine-as-fax"}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-21 20:23:38',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-21 20:00:25','2026-04-21 20:26:07');
INSERT INTO tasks VALUES('t-v0-scope','p-gtte',NULL,0,'Write docs/13-v0-scope-90-day.md','Concrete 90-day MVP. What ships: Night Handoff loop, Morning Brief, 7 OS-only capabilities (hw-bound approval, local FS gravity, local inference fallback, OS rewind, cap-sandboxed agents, OS-owned browser, provenance graph), hardcoded Chief-of-Staff Stack, cloud twin (optional). 30-60-90 milestones. Team requirements (kernel eng, NixOS ops, harness eng, UX, brand). Explicit out-of-scope list.','done','code',10,'default','2026-04-21 20:10:44','2026-04-21 20:10:44','2026-04-21 20:12:24','{"file":"docs/13-v0-scope-90-day.md","milestones":"30-60-90","oss_integrations_folded":5,"out_of_scope_items":11}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-21 20:10:44',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-21 20:00:33','2026-04-21 20:12:24');
INSERT INTO tasks VALUES('t-risks','p-gtte',NULL,0,'Write docs/14-risks-open-questions.md','Honest punch list. Technical risks: boot time, local model quality, Wayland compat, microVM perf, memory graph scale. Product risks: install friction, cold start, demo fidelity. Supply-chain risks for packs. Regulatory unknowns. Business risks: COGS at scale, competitive response. Each with mitigation or open question. Decisions-needed table.','done','code',8,'default','2026-04-21 20:12:24','2026-04-21 20:12:24','2026-04-21 20:13:29','{"decisions_needed":8,"file":"docs/14-risks-open-questions.md","risks_cataloged":31}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-21 20:12:24',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-21 20:00:36','2026-04-21 20:13:29');
INSERT INTO tasks VALUES('t-adrs','p-gtte',NULL,0,'Write ADRs (template + 0001-0004)','Create adr/README.md (process), adr/template.md (ADR template), and 4 accepted ADRs: 0001-nixos-linux-base (base choice), 0002-capability-based-security (cap-model over UID/GID), 0003-wayland-not-x11 (surface isolation), 0004-machine-as-fax-posture (legal posture for v0-v1). Each ADR: context, decision, alternatives considered (table), consequences.','done','code',7,'default','2026-04-21 20:15:21','2026-04-21 20:15:21','2026-04-21 20:17:16','{"adrs_written":5,"ids":["README","template","0001","0002","0003","0004"]}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-21 20:15:21',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-21 20:00:43','2026-04-21 20:17:16');
INSERT INTO tasks VALUES('t-diagrams','p-gtte',NULL,0,'Write mermaid diagrams (7 files)','docs/diagrams/*.mmd: layers.mmd (L0-L4), kernel-services.mmd (6 services + edges), approval-flow.mmd (action->broker->router->surface->ceremony), hax-regions.mmd (8 regions with boundary crossings), pack-lifecycle.mmd (install->grants->exec->audit), night-morning-loop.mmd (sequence diagram), memory-schema.mmd (nodes+edges).','done','code',7,'default','2026-04-21 20:17:16','2026-04-21 20:17:16','2026-04-21 20:18:29','{"diagrams":7,"files":["layers","kernel-services","approval-flow","hax-regions","pack-lifecycle","night-morning-loop","memory-schema"]}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-21 20:17:16',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-21 20:00:47','2026-04-21 20:18:29');
INSERT INTO tasks VALUES('t-reqs','p-gtte',NULL,0,'Write requirements/ (4 buckets)','docs/requirements/*.md — 4 buckets: functional.md (what Chief OS does, Night Loop contract, Pack interface), non-functional.md (reliability, observability, extensibility), security.md (threat model, cap-based rules, supply chain), performance.md (boot <10s, Morning Brief render <3s, local-model latency targets). Each bucket: append-only table of requirement IDs.','done','code',6,'default','2026-04-21 20:26:07','2026-04-21 20:26:07','2026-04-21 20:28:17','{"files":["functional","non-functional","security","performance"],"requirements_cataloged":110}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-21 20:26:07',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-21 20:00:50','2026-04-21 20:28:17');
INSERT INTO tasks VALUES('t-ideation','p-gtte',NULL,0,'Write ideation + research scaffolding','docs/ideation/README.md (how to append ideation entries), docs/ideation/2026-04-21-initial-dump.md (capture brainstorm leftovers: federation ideas, physical puck v3, enterprise trust ledger, voice-first v2, ambient display hw, agent marketplace monetization). docs/research/README.md (how to add competitor analyses, prior art, academic refs).','done','code',5,'default','2026-04-21 20:31:09','2026-04-21 20:31:09','2026-04-21 20:32:07','{"files":["ideation/README","ideation/2026-04-21-initial-dump","research/README"],"ideation_entries":1}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-21 20:31:09',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-21 20:00:54','2026-04-21 20:32:07');
